# backward compatibility: files written by icetools 0.1.2 (the version
# vendored in KITE-data that wrote every published release artifact) MUST
# keep reading correctly. fixtures/v012_fixture.ice was generated by the
# exact 0.1.2 sources (see fixtures/make-v012-fixture.R) and must never be
# regenerated with newer icetools.

test_that("a 0.1.2-written .ice file reads correctly", {
  path <- fixture_path("v012_fixture.ice")
  ice <- read_ice(path)

  expect_s3_class(ice, "ice")
  expect_identical(names(ice),
                   c("trade_share", "tariff", "sector_share",
                     "trade_elasticity", "world_gdp"))

  # exact values as staged by 0.1.2's fwrite(scipen = 999)
  expect_identical(ice$trade_share$value, c(0.75, 0.25, 0.4, 0.6))
  expect_identical(ice$trade_share$origin, c("USA", "USA", "CHN", "CHN"))

  # integral-looking numeric values: still doubles
  expect_identical(ice$tariff$value, c(1, 2, 3, 1))

  # 0.2.0 FIXES over the 0.1.2 reader, on 0.1.2-written files:
  # leading-zero character keys survive (0.1.2 read them as integers)
  expect_identical(ice$sector_share$sector, c("01", "02", "10"))
  # non-"value" value columns get the always-double guarantee
  expect_type(ice$trade_elasticity$theta, "double")
  expect_identical(ice$trade_elasticity$theta, c(4, 6))

  # keyless single-column table
  expect_identical(ice$world_gdp$value, 84.5)

  # ad hoc metadata fields attached by the KITE-data release script
  md <- attr(ice, "metadata")
  expect_identical(md$coordinates$source, "fixture")
  expect_null(md$format_version)  # pre-1.1 file
})

test_that("a 0.1.2-written .ice file passes validation (with the pre-1.2 convention warning)", {
  expect_warning(
    expect_true(suppressMessages(validate_ice(fixture_path("v012_fixture.ice")))),
    "sign convention"
  )
})

test_that("list_tables and extract_table work on a 0.1.2-written file", {
  path <- fixture_path("v012_fixture.ice")
  listing <- list_tables(path)
  expect_identical(nrow(listing), 5L)
  expect_identical(unique(listing$kind), "table")
  expect_identical(extract_table(path, "world_gdp")$value, 84.5)
})

test_that("integration: a genuine KITE-data release artifact reads and validates", {
  # opt-in: point ICETOOLS_KITE_ARTIFACT at a real artifact, or rely on a
  # local KITE-data checkout with staged releases
  candidate <- Sys.getenv("ICETOOLS_KITE_ARTIFACT", "")
  if (!nzchar(candidate)) {
    staged <- Sys.glob(file.path(path.expand("~/Repositories/KITE-data"),
                                 "releases", "staging", "*.ice"))
    candidate <- if (length(staged)) staged[1] else ""
  }
  skip_if(!nzchar(candidate) || !file.exists(candidate),
          "no KITE-data artifact available")

  ice <- suppressWarnings(read_ice(candidate))
  expect_s3_class(ice, "ice")
  expect_gt(length(ice), 0L)
  expect_true(all(vapply(ice, function(x) is.data.frame(x) || length(x) == 1L, logical(1))))
  # value columns of declared-numeric tables are doubles
  md <- attr(ice, "metadata")
  for (nm in names(md$tables)) {
    vt <- md$tables[[nm]]$value$type %||% "numeric"
    if (vt %in% c("numeric", "integer") && nm %in% names(ice)) {
      expect_type(ice[[nm]][[md$tables[[nm]]$value$name]], "double")
    }
  }
})
